      pt: "Situado em Tenerife, o parque rodeia a montanha mais alta de Espanha, o vulcão Teide. A paisagem de lava abriga plantas únicas como o tajinaste e a violeta do Teide.",
      fr: "Situé à Tenerife, le parc entoure la plus haute montagne d'Espagne, le volcan Teide. Le paysage de lave abrite des plantes uniques comme le tajinaste et la violette du Teide.",
