      es: ["Aquí vive la mayor colonia de buitres negros del mundo.", "La zona es Reserva de la Biosfera de la UNESCO desde 2003.", "Se encuentra en la confluencia de los ríos Tajo y Tiétar.", "Alcanzó el estatus de parque nacional en 2007.", "El peñón Salto del Gitano es un lugar popular para la observación de aves.", "Es de suma importancia para la protección de las águilas imperiales."],
      pt: ["Aqui vive a maior colónia de abutres-pretos do mundo.", "A zona é Reserva da Biosfera da UNESCO desde 2003.", "Encontra-se na confluência dos rios Tejo e Tiétar.", "Alcançou o estatuto de parque nacional em 2007.", "O penhasco Salto del Gitano é um lugar popular para a observação de aves.", "É de suma importância para a proteção das águias-imperiais."],
