imageHint: "Cabañeros National Park deer in plains",
    descriptionAdvanced: {
      de: "Der Nationalpark Cabañeros in der Region Kastilien-La Mancha wird oft treffend als die 'spanische Serengeti' bezeichnet und stellt eines der am besten erhaltenen Beispiele für den ursprünglichen mediterranen Wald in Europa dar. Der Park bietet eine bemerkenswerte landschaftliche Vielfalt, die von den rauen Gipfeln der Montes de Toledo bis hin zu riesigen, savannenartigen Grasebenen, den sogenannten 'Rañas', reicht. In diesen weiten Ebenen ziehen große Herden von Rotwild umher, deren majestätische Brunftrufe im Herbst das Tal erfüllen und ein unvergessliches Naturschauspiel bieten. Früher als privates Jagdrevier genutzt, ist Cabañeros heute ein streng geschütztes Refugium, das einer beeindruckenden Vielfalt von Flora und Fauna Lebensraum bietet, darunter dem stark bedrohten Iberischen Kaiseradler und dem imposanten Mönchsgeier.",
      hu: "A Kasztília-La Mancha régióban található Cabañeros Nemzeti Parkot gyakran és találóan a 'spanyol Szerengetinek' is nevezik, és az eredeti európai mediterrán erdők egyik legjobban megőrzött példáját képviseli. A park figyelemre méltó táji sokszínűséget kínál, amely a Toledo-hegység zord csúcsaitól a hatalmas, szavannaszerű füves síkságokig, az úgynevezett 'rañákig' terjed. Ezeken a tágas síkságokon hatalmas gímszarvascsordák vándorolnak, amelyek őszi, fenséges szarvasbőgése betölti a völgyet, és felejthetetlen természeti látványosságot nyújt. A korábban magán vadászterületként használt Cabañeros ma egy szigorúan védett menedékhely, amely lenyűgöző flóra- és faunának biztosít élőhelyet, köztük a súlyosan veszélyeztetett ibériai parlagi sasnak és az impozáns barátkeselyűnek.",
      ro: "Parcul Național Cabañeros din regiunea Castilia-La Mancha este adesea numit, pe bună dreptate, 'Serengeti-ul spaniol' și reprezintă unul dintre cele mai bine conservate exemple de pădure mediteraneană originală din Europa. Parcul oferă o diversitate peisagistică remarcabilă, care variază de la vârfurile aspre ale Munților Toledo până la câmpii ierboase uriașe, asemănătoare savanelor, numite 'rañas'. În aceste câmpii vaste rătăcesc turme mari de cerbi, ale căror strigăte maiestuoase de împerechere din toamnă umplu valea și oferă un spectacol natural de neuitat. Folosit anterior ca domeniu de vânătoare privat, Cabañeros este astăzi un refugiu strict protejat, care oferă habitat unei varietăți impresionante de floră și faună, inclusiv pentru acvila imperială iberică, grav amenințată, și pentru impunătorul vultur negru.",
      en: "Cabañeros National Park in the region of Castile-La Mancha is often aptly referred to as the 'Spanish Serengeti' and represents one of the best-preserved examples of pristine Mediterranean forest in Europe. The park offers remarkable landscape diversity, ranging from the rugged peaks of the Montes de Toledo to vast, savanna-like grassy plains known as 'rañas.' Large herds of red deer roam these expansive plains, and their majestic rutting calls in autumn fill the valley, providing an unforgettable natural spectacle. Formerly used as a private hunting estate, Cabañeros is today a strictly protected sanctuary that provides a habitat for an impressive variety of flora and fauna, including the critically endangered Iberian imperial eagle and the imposing black vulture.",
      es: "El Parque Nacional de Cabañeros, en la región de Castilla-La Mancha, es apodado acertadamente el 'Serengeti español' y representa uno de los ejemplos mejor conservados del bosque mediterráneo original en Europa. El parque ofrece una notable diversidad paisajística, que abarca desde las escarpadas cumbres de los Montes de Toledo hasta enormes llanuras herbáceas similares a la sabana, conocidas como 'rañas'. En estas vastas llanuras, grandes manadas de ciervos deambulan, cuyos majestuosos sonidos de celo llenan el valle en otoño, ofreciendo un espectáculo natural inolvidable. Utilizado anteriormente como coto de caza privado, Cabañeros es hoy un refugio estrictamente protegido que ofrece hábitat a una impresionante variedad de flora y fauna, incluido el gravemente amenazado águila imperial ibérica y el imponente buitre negro.",
      pt: "O Parque Nacional de Cabañeros, na região de Castela-Mancha, é apropriadamente apelidado de 'Serengeti espanhol' e representa um dos exemplos mais bem preservados da floresta mediterrânica original na Europa. O parque oferece uma notável diversidade paisagística, desde os cumes escarpados dos Montes de Toledo até às enormes planícies herbáceas semelhantes à savana, conhecidas como 'rañas'. Nestas vastas planícies, grandes manadas de veados vagueiam, cujos majestosos bramidos enchem o vale no outono, oferecendo um espetáculo natural inesquecível. Anteriormente utilizado como reserva de caça privada, Cabañeros é hoje um refúgio estritamente protegido que oferece habitat a uma impressionante variedade de flora e fauna, incluindo a criticamente ameaçada águia-imperial-ibérica e o imponente abutre-preto.",
      fr: "Le parc national de Cabañeros, dans la région de Castille-La Manche, est surnommé à juste titre le « Serengeti espagnol » et représente l'un des exemples les mieux conservés de forêt méditerranéenne originelle en Europe. Le parc offre une diversité paysagère remarquable, allant des sommets escarpés des monts de Tolède aux immenses plaines herbeuses ressemblant à la savane, appelées « rañas ». Dans ces vastes plaines, de grands troupeaux de cerfs se promènent, dont les majestueux brames remplissent la vallée en automne, offrant un spectacle naturel inoubliable. Autrefois utilisé comme réserve de chasse privée, Cabañeros est aujourd'hui un refuge strictement protégé offrant un habitat à une impressionnante variété de flore et de faune, notamment l'aigle ibérique, gravement menacé, et l'imposant vautour moine.",
    },
