imageHint: "Tablas de Daimiel National Park wetlands boardwalk",
    descriptionAdvanced: {
      de: "Der Nationalpark Tablas de Daimiel in der Region Kastilien-La Mancha ist das letzte und wertvollste Überbleibsel eines einst weitläufigen Systems von 'Fluvialen Tablas', einzigartigen Überschwemmungsgebieten im Herzen der Iberischen Halbinsel. Dieses bemerkenswerte Feuchtgebiet entsteht an der Stelle, wo das leicht salzige Wasser des Flusses Gigüela mit dem Süßwasser des Flusses Guadiana zusammentrifft und die flache La Mancha-Ebene überflutet. Dieses Miteinander der Gewässer schafft ein ideales Mikroklima und ein üppiges Ökosystem, das von dichten Schilfgürteln und Sumpfpflanzen dominiert wird. Für unzählige Wasservögel, insbesondere Enten, Reiher und seltene Zugvögel, ist Daimiel ein unverzichtbarer Brut- und Überwinterungsplatz. Trotz der ständigen Bedrohung durch landwirtschaftliche Übernutzung der Grundwasserleiter wird dieses Ramsar-Gebiet intensiv geschützt und über malerische Holzstege für Besucher zugänglich gemacht.",
      hu: "A Kasztília-La Mancha régióban található Tablas de Daimiel Nemzeti Park az utolsó és legértékesebb maradványa a 'folyami táblák' (Tablas Fluviales) egykor kiterjedt rendszerének, amely az Ibériai-félsziget szívének egyedülálló ártéri ökoszisztémája. Ez a figyelemre méltó vizes élőhely azon a helyen jön létre, ahol a Gigüela folyó enyhén sós vize találkozik a Guadiana folyó édesvizével, és elárasztja a lapos La Mancha-síkságot. A vizek ezen keveredése ideális mikroklímát és buja ökoszisztémát teremt, amelyet sűrű nádasok és mocsári növények uralnak. Számtalan vízimadár, különösen kacsák, gémek és ritka vándormadarak számára Daimiel nélkülözhetetlen fészkelő- és telelőhely. Bár a talajvíz mezőgazdasági túlhasználata folyamatosan fenyegeti, ezt a Ramsari területet intenzíven védik, és festői fapallókon teszik látogathatóvá.",
      ro: "Parcul Național Tablas de Daimiel din regiunea Castilia-La Mancha este ultima și cea mai valoroasă rămășiță a unui sistem cândva vast de 'Tablas Fluviale', ecosisteme de luncă inundabilă unice în inima Peninsulei Iberice. Această zonă umedă remarcabilă se formează în locul în care apele ușor sărate ale râului Gigüela se întâlnesc cu apele dulci ale râului Guadiana și inundă câmpia plată La Mancha. Această interacțiune a apelor creează un microclimat ideal și un ecosistem luxuriant, dominat de centuri dense de stuf și plante de mlaștină. Pentru nenumărate păsări de apă, în special rațe, stârci și păsări migratoare rare, Daimiel este un loc de cuibărit și de iernat indispensabil. În ciuda amenințării constante cauzate de supraexploatarea agricolă a acviferelor, acest sit Ramsar este intens protejat și este accesibil vizitatorilor prin pasarele pitorești din lemn.",
      en: "The Tablas de Daimiel National Park in the region of Castile-La Mancha is the last and most valuable remnant of a once-extensive system of 'Fluvial Tablas,' unique floodplain ecosystems in the heart of the Iberian Peninsula. This remarkable wetland forms where the slightly saline waters of the Gigüela River meet the fresh water of the Guadiana River, flooding the flat La Mancha plain. This merging of waters creates an ideal microclimate and a lush ecosystem dominated by dense reed beds and marsh plants. For countless waterbirds, especially ducks, herons, and rare migratory birds, Daimiel is an indispensable nesting and wintering site. Despite the constant threat posed by agricultural overexploitation of the aquifers, this Ramsar site is intensely protected and made accessible to visitors via picturesque wooden boardwalks.",
      es: "El Parque Nacional Tablas de Daimiel en la región de Castilla-La Mancha es el último y más valioso vestigio de un sistema alguna vez extenso de 'Tablas Fluviales', humedales únicos en el corazón de la Península Ibérica. Este notable humedal se crea en el lugar donde el agua ligeramente salada del río Gigüela se encuentra con el agua dulce del río Guadiana e inunda la plana llanura de La Mancha. Esta interacción de las aguas crea un microclima ideal y un ecosistema exuberante dominado por densos cinturones de juncos y plantas de pantano. Para innumerables aves acuáticas, especialmente patos, garzas y aves migratorias raras, Daimiel es un lugar indispensable de cría e invernada. A pesar de la amenaza constante por el sobreuso agrícola de los acuíferos, este sitio Ramsar está intensamente protegido y hecho accesible a los visitantes a través de pintorescas pasarelas de madera.",
      pt: "O Parque Nacional Tablas de Daimiel, na região de Castela-La Mancha, é o último e mais valioso vestígio de um sistema outrora extenso de 'Tablas Fluviales', zonas húmidas únicas no coração da Península Ibérica. Esta notável zona húmida é criada no local onde a água ligeiramente salgada do rio Gigüela encontra a água doce do rio Guadiana e inunda a plana planície de La Mancha. Esta interação das águas cria um microclima ideal e um ecossistema exuberante dominado por densos cinturões de juncos e plantas de pântano. Para inúmeras aves aquáticas, especialmente patos, garças e aves migratórias raras, Daimiel é um local indispensável de reprodução e invernada. Apesar da ameaça constante devido à sobreutilização agrícola dos aquíferos, este sítio Ramsar está intensamente protegido e tornado acessível aos visitantes através de pitorescas passarelas de madeira.",
      fr: "Le parc national de Tablas de Daimiel dans la région de Castille-La Manche est le dernier et le plus précieux vestige d'un système autrefois étendu de 'Tablas Fluviales', des zones humides uniques au cœur de la péninsule Ibérique. Cette remarquable zone humide se crée à l'endroit où l'eau légèrement salée de la rivière Gigüela rencontre l'eau douce de la rivière Guadiana et inonde la plaine plate de La Mancha. Cette interaction des eaux crée un microclimat idéal et un écosystème luxuriant dominé par des ceintures denses de roseaux et de plantes marécageuses. Pour d'innombrables oiseaux aquatiques, notamment les canards, les hérons et les oiseaux migrateurs rares, Daimiel est un lieu indispensable de nidification et d'hivernage. Malgré la menace constante due à la surexploitation agricole des aquifères, ce site Ramsar est intensément protégé et rendu accessible aux visiteurs par des passerelles en bois pittoresques.",
    },
