imageHint: "Garajonay National Park misty laurel forest",
    descriptionAdvanced: {
      de: "Der Nationalpark Garajonay befindet sich im Zentrum der Kanareninsel La Gomera und ist berühmt für seinen außergewöhnlich gut erhaltenen Lorbeerwald (Laurisilva). Dieser Waldtyp bedeckte im Tertiär weite Teile Südeuropas und Nordafrikas und hat hier aufgrund des milden Klimas und der ständigen Nebelbildung durch die Passatwinde überlebt. Der Park erstreckt sich über eine Fläche von fast 4.000 Hektar und umfasst den höchsten Punkt der Insel, den Alto de Garajonay mit 1.487 Metern. Die üppige Vegetation besteht aus Baumheide, Lorbeerbäumen und zahlreichen Farn- und Moosarten, die durch den sogenannten horizontalen Regen bewässert werden. Garajonay beherbergt eine hohe Anzahl endemischer Tier- und Pflanzenarten, darunter seltene Taubenarten wie die Lorbeertaube. Aufgrund seiner ökologischen Einzigartigkeit wurde der Park 1986 von der UNESCO zum Weltnaturerbe erklärt. Er gilt als lebendiges Fossil und ist ein wichtiges Schutzgebiet für die Erhaltung der prähistorischen Flora der Makaronesischen Inseln.",
      hu: "A Garajonay Nemzeti Park La Gomera szigetének közepén található, és világhírű a kivételesen jó állapotban fennmaradt babérlombú erdejéről (laurisilva). Ez az erdőtípus a harmadkorban még Dél-Európa és Észak-Afrika jelentős részét borította, de itt a kedvező éghajlat és a passzátszelek okozta állandó ködképződés miatt fennmaradt. A park közel 4000 hektáron terül el, és magában foglalja a sziget legmagasabb pontját, az 1487 méteres Alto de Garajonayt. A buja növényzetet főként babérfák, hangafák és számos páfrány- és mohafaj alkotja, amelyeket az úgynevezett horizontális eső táplál. A Garajonay számos endemikus állat- és növényfaj otthona, köztük olyan ritka madaraké, mint a szürkefarkú babérgalamb. Ökológiai egyedisége miatt az UNESCO 1986-ban a Világörökség részévé nyilvánította. Az erdő egyfajta élő kövület, amely bepillantást enged a makaronéziai szigetvilág prehisztorikus flórájába.",
      ro: "Parcul Național Garajonay este situat în centrul insulei La Gomera din Arhipelagul Canare și este celebru pentru pădurea sa de lauri (laurisilva) excepțional de bine conservată. Acest tip de pădure acoperea mari părți din sudul Europei și nordul Africii în perioada terțiară, supraviețuind aici datorită climatului blând și ceții persistente formate de vânturile alizee. Parcul se întinde pe o suprafață de aproape 4.000 de hectare și include cel mai înalt punct al insulei, Alto de Garajonay, la 1.487 de metri. Vegetația luxuriantă este compusă din copaci de laur, ferigi gigantice și mușchi, hrănite de ploaia orizontală provenită din condensarea norilor. Garajonay adăpostește numeroase specii endemice de floră și faună, inclusiv porumbelul de laur, o specie rară. Datorită unicității sale ecologice, parcul a fost inclus în Patrimoniul Mondial UNESCO în 1986, fiind considerat o fosilă vie a ecosistemelor preistorice.",
      en: "Garajonay National Park is located in the center of the island of La Gomera in the Canary Islands and is renowned for its exceptionally well-preserved laurel forest (laurisilva). This type of forest covered much of Southern Europe and North Africa during the Tertiary period but has survived here due to the mild climate and constant mist generated by trade winds. The park spans nearly 4,000 hectares and encompasses the islands highest point, the Alto de Garajonay at 1,487 meters. The lush vegetation consists of laurel trees, giant heathers, and numerous fern and moss species, all sustained by what is known as horizontal rain from cloud condensation. Garajonay is home to a high number of endemic species, including rare birds like the Bolles pigeon. Because of its ecological uniqueness, UNESCO designated the park a World Heritage site in 1986. It serves as a living fossil, preserving the prehistoric flora of the Macaronesian islands.",
      es: "El Parque Nacional de Garajonay, en la isla canaria de La Gomera, es un lugar místico que transporta a sus visitantes a una época geológica pasada. El parque protege la mayor zona existente de laurisilva (bosque de laurel), una exuberante vegetación perenne que cubría gran parte del sur de Europa y el norte de África en el Terciario y que hoy ha desaparecido casi por completo. Este bosque encantado se mantiene gracias a un fenómeno único: los vientos alisios. Estos vientos empujan masas de aire húmedo contra las montañas, donde se condensan y envuelven el bosque en una niebla constante y densa. La llamada 'precipitación de niebla' empapa musgos, helechos y lianas que crecen densamente en los árboles. Además de su riqueza botánica, Garajonay alberga una asombrosa variedad de animales invertebrados y aves endémicas.",
      pt: "O Parque Nacional de Garajonay, na ilha canária de La Gomera, é um lugar místico que transporta os seus visitantes para uma época geológica passada. O parque protege a maior área existente de laurissilva (bosque de louros), uma vegetação luxuriante e perene que cobria grande parte do sul da Europa e norte de África no Terciário e que hoje quase desapareceu. Este bosque encantado é mantido graças a um fenómeno único: os ventos alísios. Estes ventos empurram massas de ar húmido contra as montanhas, onde condensam e envolvem o bosque numa névoa constante e densa. A chamada 'precipitação da névoa' encharca musgos, fetos e lianas que crescem densamente nas árvores. Além da sua riqueza botânica, Garajonay alberga uma variedade surpreendente de animais invertebrados e aves endémicas.",
      fr: "Le parc national de Garajonay, sur l'île canarienne de La Gomera, est un lieu mystique qui transporte ses visiteurs dans une époque géologique révolue. Le parc protège la plus grande zone existante de laurisylve (forêt de lauriers), une végétation luxuriante et persistante qui couvrait une grande partie du sud de l'Europe et de l'Afrique du Nord à l'ère tertiaire et qui a presque disparu aujourd'hui. Cette forêt enchantée est maintenue en vie grâce à un phénomène unique : les alizés. Ces vents poussent des masses d'air humide contre les montagnes, où elles se condensent et enveloppent la forêt dans un brouillard constant et dense. La soi-disant « précipitation de brouillard » imprègne les mousses, les fougères et les lianes qui poussent densément sur les arbres. Outre sa richesse botanique, Garajonay abrite une étonnante variété d'invertébrés et d'oiseaux endémiques.",
    },
