imageHint: "Caldera de Taburiente National Park landscape La Palma",
    descriptionAdvanced: {
      de: "Der Nationalpark Caldera de Taburiente auf der Kanareninsel La Palma umschließt eines der beeindruckendsten geologischen Gebilde der Erde: einen gigantischen Erosionskrater mit einem Durchmesser von acht Kilometern und steil abfallenden Wänden, die bis zu 2000 Meter in die Tiefe stürzen. Diese zerklüftete Caldera ist dicht bewachsen mit dem widerstandsfähigen Kanarischen Kiefernwald, der selbst Waldbrände überstehen kann. Das zerklüftete Terrain ist von einem dichten Netz aus Bächen und Wasserfällen durchzogen, von denen die berühmte Cascada de los Colores (Bunter Wasserfall), deren Wasser durch Eisen- und Mineralablagerungen in leuchtenden Gelb-, Orange- und Grüntönen gefärbt ist, besonders hervorsticht. Am höchsten Rand der Caldera thront der Roque de los Muchachos, wo aufgrund der außergewöhnlichen Luftklarheit eines der wichtigsten astrophysikalischen Observatorien der Welt angesiedelt ist.",
      hu: "A La Palma Kanári-szigeten található Caldera de Taburiente Nemzeti Park a Föld egyik leglenyűgözőbb geológiai képződményét öleli körül: egy gigantikus, nyolc kilométer átmérőjű eróziós krátert, amelynek meredek falai akár 2000 méteres mélységbe is aláhullanak. Ezt a tagolt kalderát sűrűn borítja az ellenálló kanári fenyőerdő, amely még az erdőtüzeket is képes túlélni. A zord terepet patakok és vízesések sűrű hálózata szövi át, amelyek közül kiemelkedik a híres Cascada de los Colores (Színes vízesés), melynek vizét a vas- és ásványi lerakódások élénk sárga, narancssárga és zöld árnyalatúra festik. A kaldera legmagasabb peremén magasodik a Roque de los Muchachos, ahol a rendkívüli levegőtisztaság miatt a világ egyik legfontosabb asztrofizikai obszervatóriuma kapott helyet.",
      ro: "Parcul Național Caldera de Taburiente de pe insula canariană La Palma înconjoară una dintre cele mai impresionante formațiuni geologice de pe Pământ: un crater de eroziune gigantic cu un diametru de opt kilometri și pereți abrupți care cad până la 2000 de metri în adâncime. Această calderă fragmentată este acoperită dens de pădurea rezistentă de pini canarieni, care poate supraviețui chiar și incendiilor forestiere. Terenul accidentat este străbătut de o rețea densă de pâraie și cascade, dintre care se remarcă în mod deosebit faimoasa Cascada de los Colores (Cascada Colorată), a cărei apă este colorată în nuanțe vii de galben, portocaliu și verde de depozitele de fier și minerale. Pe marginea cea mai înaltă a calderei se înalță Roque de los Muchachos, unde, datorită clarității excepționale a aerului, se află unul dintre cele mai importante observatoare astrofizice din lume.",
      en: "The Caldera de Taburiente National Park on the Canary Island of La Palma encompasses one of the most impressive geological formations on Earth: a gigantic erosion crater eight kilometers in diameter with sheer walls that plummet up to 2,000 meters into the depths. This rugged caldera is densely covered by resilient Canary Island pine forests, which can even survive wildfires. The rugged terrain is crisscrossed by a dense network of streams and waterfalls, most notably the famous Cascada de los Colores (Colored Waterfall), whose waters are dyed vibrant shades of yellow, orange, and green by iron and mineral deposits. Perched on the highest rim of the caldera is the Roque de los Muchachos, home to one of the world's most important astrophysical observatories due to the exceptional clarity of the air.",
      es: "El Parque Nacional de la Caldera de Taburiente, en la isla canaria de La Palma, encierra una de las formaciones geológicas más impresionantes de la Tierra: un gigantesco cráter de erosión de ocho kilómetros de diámetro y paredes que caen abruptamente hasta 2000 metros de profundidad. Esta caldera escarpada está densamente cubierta por el resistente bosque de pino canario, capaz de sobrevivir incluso a los incendios forestales. El terreno abrupto está surcado por una densa red de arroyos y cascadas, entre las que destaca la famosa Cascada de los Colores, cuyas aguas están teñidas de brillantes tonos amarillos, naranjas y verdes debido a los depósitos de hierro y minerales. En el borde más alto de la caldera se encuentra el Roque de los Muchachos, donde, debido a la excepcional claridad del aire, se encuentra uno de los observatorios astrofísicos más importantes del mundo.",
      pt: "O Parque Nacional da Caldera de Taburiente, na ilha canária de La Palma, encerra uma das formações geológicas mais impressionantes da Terra: uma gigantesca cratera de erosão com oito quilómetros de diâmetro e paredes que descem abruptamente até 2000 metros de profundidade. Esta caldeira escarpada está densamente coberta pela resistente floresta de pinheiro-das-canárias, capaz de sobreviver até mesmo a incêndios florestais. O terreno acidentado é atravessado por uma densa rede de riachos e cascatas, entre as quais se destaca a famosa Cascada de los Colores (Cascata das Cores), cujas águas estão tingidas de tons brilhantes de amarelo, laranja e verde devido aos depósitos de ferro e minerais. Na orla mais alta da caldeira ergue-se o Roque de los Muchachos, onde, devido à clareza excecional do ar, se encontra um dos observatórios astrofísicos mais importantes do mundo.",
      fr: "Le parc national de Caldera de Taburiente, sur l'île canarienne de La Palma, renferme l'une des formations géologiques les plus impressionnantes de la Terre : un gigantesque cratère d'érosion de huit kilomètres de diamètre avec des parois tombant abruptement jusqu'à 2 000 mètres de profondeur. Cette caldeira escarpée est densément recouverte par la forêt résistante de pins canariens, capable de survivre même aux incendies de forêt. Le terrain accidenté est traversé par un réseau dense de ruisseaux et de cascades, parmi lesquelles se distingue la célèbre Cascada de los Colores (Cascade des Couleurs), dont l'eau est teintée de tons vifs jaunes, orange et verts dus aux dépôts de fer et de minéraux. Sur le bord le plus élevé de la caldeira se trouve le Roque de los Muchachos, où, en raison de la clarté exceptionnelle de l'air, se situe l'un des observatoires astrophysiques les plus importants du monde.",
    },
