      de: ["A kaldera átmérője eléri a 8 kilométert.", "Legmagasabb pontja, a Roque de los Muchachos 2426 méter magas.", "1954-ben kapott nemzeti parki státuszt.", "Híres a Cascada de los Colores (Színes vízesés) nevű geológiai csodájáról.", "A világ egyik legtisztább levegőjű területe, ideális csillagvizsgálathoz.", "Az itt élő kanári fenyő tűzálló kéreggel rendelkezik."],
