      pt: ["O diâmetro da caldeira atinge 8 quilómetros.", "O seu ponto mais alto, o Roque de los Muchachos, tem 2426 metros.", "Recebeu o estatuto de parque nacional em 1954.", "Famoso pela sua maravilha geológica, a Cascada de los Colores.", "É uma das zonas com o ar mais limpo do mundo, ideal para a observação de estrelas.", "O pinheiro-das-canárias que cresce aqui tem uma casca resistente ao fogo."],
      fr: ["Le diamètre de la caldeira atteint 8 kilomètres.", "Son point culminant, le Roque de los Muchachos, atteint 2 426 mètres.", "Il a reçu le statut de parc national en 1954.", "Célèbre pour sa merveille géologique, la Cascada de los Colores.", "C'est l'une des zones à l'air le plus pur du monde, idéale pour l'observation des étoiles.", "Le pin canarien qui pousse ici possède une écorce résistante au feu."],
