imageHint: "Estany de Sant Maurici lake Pyrenees",
    descriptionAdvanced: {
      de: "Der Nationalpark Aigüestortes i Estany de Sant Maurici liegt in den katalanischen Pyrenäen und ist das Land der tausend Seen. Er beherbergt über 200 kristallklare, tiefblaue Bergseen (Estanys), die als Zeugen der letzten Eiszeit in den felsigen Mulden der Hochgebirgslandschaft ruhen. Der Name 'Aigüestortes' (Gewundene Gewässer) bezieht sich auf die zahlreichen Bäche und Flüsse, die sich malerisch in weiten Schleifen durch die flachen Hochtäler winden und ein einzigartiges Feuchtgebiets-Ökosystem schaffen. Die majestätischen, oft schneebedeckten Gipfel, darunter die markante Doppelspitze der 'Els Encantats' (Die Verzauberten), überragen dichte Wälder aus Bergkiefern und Tannen. In dieser abgeschiedenen und rauen Umgebung finden zahlreiche geschützte Tierarten wie das Auerhuhn, das Murmeltier, der Steinadler und die Pyrenäen-Gämse ideale Lebensbedingungen.",
      hu: "A katalán Pireneusokban található Aigüestortes i Estany de Sant Maurici Nemzeti Park az ezer tó hazája. Több mint 200 kristálytiszta, mélykék hegyi tó (estany) található itt, amelyek az utolsó jégkorszak tanúiként pihennek a magashegyi táj sziklás medencéiben. Az 'Aigüestortes' (kanyargós vizek) név arra a számtalan patakra és folyóra utal, amelyek festőien, széles kanyarulatokban kanyarognak a lapos magasvölgyekben, és egyedülálló vizes élőhelyi ökoszisztémát hoznak létre. A fenséges, gyakran hóval borított csúcsok, köztük az 'Els Encantats' (Az elvarázsoltak) jellegzetes kettős hegycsúcsa, sűrű hegyi fenyőkből és jegenyefenyőkből álló erdők fölé magasodnak. Ebben az elzárt és zord környezetben számos védett állatfaj, mint például a siketfajd, a mormota, a szirti sas és a pireneusi zerge talál ideális életfeltételekre.",
      ro: "Parcul Național Aigüestortes i Estany de Sant Maurici este situat în Pirineii catalani și este ținutul celor o mie de lacuri. Găzduiește peste 200 de lacuri montane (estanys) cristaline, de un albastru profund, care se odihnesc în depresiunile stâncoase ale peisajului montan înalt, ca martori ai ultimei ere glaciare. Numele 'Aigüestortes' (Ape șerpuite) se referă la numeroasele pâraie și râuri care se ondulează pitoresc în bucle largi prin văile înalte și plate, creând un ecosistem unic de zonă umedă. Vârfurile maiestuoase, adesea acoperite de zăpadă, inclusiv vârful dublu distinctiv al 'Els Encantats' (Cei Vrăjiți), se înalță deasupra pădurilor dense de pini de munte și brazi. În acest mediu izolat și aspru, numeroase specii de animale protejate, cum ar fi cocoșul de munte, marmota, acvila de munte și capra neagră din Pirinei, găsesc condiții ideale de viață.",
      en: "The Aigüestortes i Estany de Sant Maurici National Park is located in the Catalan Pyrenees and is known as the land of a thousand lakes. It is home to over 200 crystal-clear, deep-blue mountain lakes (estanys), which rest in the rocky hollows of the high mountain landscape as silent witnesses to the last Ice Age. The name 'Aigüestortes' (Winding Waters) refers to the numerous streams and rivers that meander picturesquely in wide loops through the flat, high valleys, creating a unique wetland ecosystem. The majestic, often snow-capped peaks, including the distinctive double summit of the 'Els Encantats' (The Enchanted Ones), tower above dense forests of mountain pines and firs. In this remote and rugged environment, numerous protected animal species, such as the western capercaillie, the marmot, the golden eagle, and the Pyrenean chamois, find ideal living conditions.",
      es: "El Parque Nacional de Aigüestortes i Estany de Sant Maurici se encuentra en los Pirineos catalanes y es la tierra de los mil lagos. Alberga más de 200 lagos de montaña de color azul profundo y aguas cristalinas, testigos de la última edad de hielo en las cuencas rocosas del paisaje de alta montaña. El nombre 'Aigüestortes' (Aguas torcidas) se refiere a los numerosos arroyos y ríos que serpentean pintorescamente en amplias curvas por los valles altos y crean un ecosistema de humedales único. Las majestuosas cumbres, a menudo nevadas, incluida la impresionante doble cima de 'Els Encantats', dominan los densos bosques de pinos y abetos. En este entorno aislado y agreste, especies protegidas como el urogallo, la marmota, el águila real y el rebeco pirenaico encuentran condiciones de vida ideales.",
      pt: "O Parque Nacional de Aigüestortes i Estany de Sant Maurici fica nos Pirenéus catalães e é a terra dos mil lagos. Abriga mais de 200 lagos de montanha de cor azul profundo e águas cristalinas, testemunhas da última era glacial nas bacias rochosas da paisagem de alta montanha. O nome 'Aigüestortes' (Águas tortas) refere-se aos numerosos ribeiros e rios que serpenteiam pitorescamente em amplas curvas pelos vales altos e criam um ecossistema de zonas húmidas único. Os majestosos cumes, muitas vezes cobertos de neve, incluindo o impressionante pico duplo de 'Els Encantats', dominam as densas florestas de pinheiros e abetos. Neste ambiente isolado e agreste, espécies protegidas como o tetraz, a marmota, a águia-real e o camurça-pirenaica encontram condições de vida ideais.",
      fr: "Le parc national d'Aigüestortes i Estany de Sant Maurici se trouve dans les Pyrénées catalanes et est la terre des mille lacs. Il abrite plus de 200 lacs de montagne d'un bleu profond aux eaux cristallines, témoins de la dernière ère glaciaire dans les bassins rocheux du paysage de haute montagne. Le nom 'Aigüestortes' (Eaux tordues) fait référence aux nombreux ruisseaux et rivières qui serpentent de manière pittoresque dans de larges courbes à travers les hautes vallées, créant un écosystème de zones humides unique. Les sommets majestueux, souvent enneigés, y compris le double pic impressionnant d' 'Els Encantats', dominent les forêts denses de pins et de sapins. Dans cet environnement isolé et rude, des espèces protégées comme le grand tétras, la marmotte, l'aigle royal et le chamois pyrénéen trouvent des conditions de vie idéales.",
    },
    factsAdvanced: {
      de: ["A parkban több mint 200 természetes hegyi tó található.", "Katalónia egyetlen hivatalos nemzeti parkja.", "Az Els Encantats (Az elvarázsoltak) ikercsúcs a legismertebb sziklaalakzata.", "Az 'Aigüestortes' név a völgyekben kanyargó vizekre utal.", "Legmagasabb pontja, a Comaloforno csúcs 3029 méter magas.", "Gazdag populációja van a pireneusi zergékből."],
      hu: [],
      ro: [],
      en: [],
      es: ["El parque tiene más de 200 lagos naturales de montaña.", "Es el único parque nacional oficial de Cataluña.", "El pico gemelo 'Els Encantats' es su formación rocosa más famosa.", "El nombre 'Aigüestortes' alude a las aguas que serpentean en los valles.", "Su punto más alto, el pico Comaloforno, tiene 3029 metros.", "Tiene una rica población de rebecos pirenaicos."],
      pt: ["O parque tem mais de 200 lagos naturais de montanha.", "É o único parque nacional oficial da Catalunha.", "O pico gémeo 'Els Encantats' é a sua formação rochosa mais famosa.", "O nome 'Aigüestortes' alude às águas que serpenteiam nos vales.", "O seu ponto mais alto, o pico Comaloforno, tem 3029 metros.", "Tem uma rica população de camurças-pirenaicas."],
      fr: ["Le parc compte plus de 200 lacs de montagne naturels.", "C'est le seul parc national officiel de Catalogne.", "Le pic jumeau 'Els Encantats' est sa formation rocheuse la plus célèbre.", "Le nom 'Aigüestortes' fait allusion aux eaux qui serpentent dans les vallées.", "Son point culminant, le pic Comaloforno, culmine à 3029 mètres.", "Il possède une riche population de chamois pyrénéens."],
    },
