      pt: ["Peñalara é o pico mais alto (2428 m)", "Habitat da águia-imperial", "Conhecido pelas rochas de La Pedriza", "Destino frequente para excursionistas madrilenos"],
      fr: ["Peñalara est le plus haut sommet (2428 m)", "Habitat de l'aigle impérial", "Connu pour les rochers de La Pedriza", "Destination fréquente pour les excursionnistes madrilènes"],
