      es: ["Fue declarado 15º parque nacional de España en 2013.", "El pico Peñalara es el punto más alto del parque con 2428 metros.", "La Pedriza es una de las formaciones rocosas de granito más importantes de Europa.", "Es muy popular entre los madrileños debido a su cercanía.", "Es uno de los últimos baluartes del águila imperial ibérica.", "Está cubierto por extensos bosques de pino albar (Pinus sylvestris)."],
      pt: ["Foi declarado 15º parque nacional de Espanha em 2013.", "O pico Peñalara é o ponto mais alto do parque com 2428 metros.", "La Pedriza é uma das formações rochosas de granito mais importantes da Europa.", "É muito popular entre os madrilenos devido à sua proximidade.", "É um dos últimos redutos da águia-imperial-ibérica.", "Está coberto por extensos bosques de pinheiro-silvestre (Pinus sylvestris)."],
      fr: ["Il a été déclaré 15e parc national d'Espagne en 2013.", "Le pic Peñalara est le point culminant du parc avec 2428 mètres.", "La Pedriza est l'une des formations rocheuses de granit les plus importantes d'Europe.", "Il est très populaire auprès des Madrilènes en raison de sa proximité.", "C'est l'un des derniers bastions de l'aigle impérial ibérique.", "Il est couvert par de vastes forêts de pin sylvestre (Pinus sylvestris)."],
