    description: {
      de: "Im Kantabrischen Gebirge gelegen, ist Somiedo eines der wichtigsten Rückzugsgebiete des Braunbären in Spanien. Es ist bekannt für seine Gletscherseen und die traditionellen 'Teitos'-Hütten.",
      hu: "A Kantábriai-hegységben található Somiedo a barna medve egyik legfontosabb menedékhelye Spanyolországban. Gleccsertavairól és a hagyományos 'teitos' kunyhókról ismert.",
      ro: "Situat în Munții Cantabrici, Somiedo este unul dintre cele mai importante refugii ale ursului brun din Spania. Este cunoscut pentru lacurile sale glaciare și colibele tradiționale 'teitos'.",
      en: "Located in the Cantabrian Mountains, Somiedo is one of the most important refuges for the brown bear in Spain. It is known for its glacial lakes and traditional 'teitos' huts.",
      es: "Situado en la Cordillera Cantábrica, Somiedo es una de las zonas de refugio más importantes para el oso pardo en España. Es conocido por sus lagos glaciares y las tradicionales cabañas 'teitos'.",
      pt: "Situado na Cordilheira Cantábrica, Somiedo é uma das zonas de refúgio mais importantes para o urso-pardo em Espanha. É conhecido pelos seus lagos glaciares e pelas tradicionais cabanas 'teitos'.",
      fr: "Situé dans la cordillère Cantabrique, Somiedo est l'une des zones de refuge les plus importantes pour l'ours brun en Espagne. Il est connu pour ses lacs glaciaires et ses cabanes traditionnelles 'teitos'.",
    },
