      en: ["Largest natural park in Spain", "Source of the Guadalquivir River", "Area exceeds 209,000 hectares", "UNESCO Biosphere Reserve since 1983", "Home to over 2,300 plant species", "Habitat for the rare bearded vulture"],
      es: ["El parque fue fundado en 1986.", "Abarca 2.099 kilómetros cuadrados.", "El punto más alto es el Pico de Cabañas con 2.027 metros.", "Hay más de 1.300 especies de plantas.", "El Guadalquivir mide 657 kilómetros de largo.", "El lince ibérico tiene aquí una población de unas 50 unidades."],
