      fr: ["Le parc a été fondé en 1986.", "Il couvre 2 099 kilomètres carrés.", "Le point culminant est le Pico de Cabañas avec 2 027 mètres.", "Il existe plus de 1 300 espèces de plantes.", "Le Guadalquivir mesure 657 kilomètres de long.", "Le lynx ibérique possède ici une population d'environ 50 individus."],
