      de: ["Erster maritim-terrestrischer Naturpark", "Zahlreiche Flamingos in den Salinen", "Besondere Agaven-Vegetation", "Häufige Filmkulisse"],
      hu: ["Az első tengeri-szárazföldi természeti park", "Számos flamingó a sós mocsarakban", "Különleges agávé vegetáció", "Gyakori filmforgatási helyszín"],
