      es: ["Primer parque natural marítimo-terrestre", "Numerosos flamencos en las salinas", "Vegetación especial de agaves", "Frecuente escenario de cine"],
      pt: ["Primeiro parque natural marítimo-terrestre", "Numerosos flamingos nas salinas", "Vegetação especial de agaves", "Cenário frequente de cinema"],
