      en: [],
      es: ["Con más de 320 kilómetros cuadrados, es el mayor humedal de Cataluña.", "Se practica el cultivo extensivo de arroz en los suelos fértiles del delta.", "Se han observado más de 300 especies de aves en su territorio.", "Alberga una colonia permanente e importante de flamencos.", "Amenazado por la subida del nivel del mar debido al cambio climático.", "Destino popular de ecoturismo y ciclismo por el terreno llano."],
      pt: ["Com mais de 320 quilómetros quadrados, é a maior zona húmida da Catalunha.", "Pratica-se o cultivo extensivo de arroz nos solos férteis do delta.", "Foram observadas mais de 300 espécies de aves no seu território.", "Abriga uma colónia permanente e importante de flamingos.", "Ameaçado pelo aumento do nível do mar devido às alterações climáticas.", "Destino popular de ecoturismo e ciclismo devido ao terreno plano."],
      fr: ["Avec plus de 320 kilomètres carrés, c'est la plus grande zone humide de Catalogne.", "La culture extensive du riz est pratiquée sur les sols fertiles du delta.", "Plus de 300 espèces d'oiseaux ont été observées sur son territoire.", "Il abrite une importante colonie permanente de flamants roses.", "Menacé par l'élévation du niveau de la mer due au changement climatique.", "Destination populaire d'écotourisme et de cyclisme en raison du terrain plat."],
