      pt: ["O maior lago de Espanha, com mais de 21 km².", "Declarado parque natural protegido em 1986.", "Local de origem da paella valenciana tradicional.", "Rede de arrozais rodeia a lagoa.", "De grande importância para a nidificação de garças e aves aquáticas.", "Separado do mar pela faixa de areia 'Dehesa del Saler'."],
