    description: {
      de: "In einer ehemaligen Eisenerzmine in Kantabrien gelegen, leben hier Tiere aus fünf Kontinenten in halbfreier Wildbahn. Der Park ist für seine weitläufigen Gehege in einer bizarren Karstlandschaft bekannt.",
      hu: "Egy korábbi vasércbányában található Kantábriában, ahol öt kontinens állatai élnek félszabad környezetben. A park tágas kifutóiról és bizarr karszttájáról ismert.",
      ro: "Situat într-o fostă mină de fier din Cantabria, aici trăiesc animale de pe cinci continente în semi-libertate. Parcul este cunoscut pentru incintele sale vaste într-un peisaj carstic bizar.",
      en: "Located in a former iron mine in Cantabria, animals from five continents live here in semi-free conditions. The park is known for its vast enclosures in a bizarre karst landscape.",
      es: "Situado en una antigua mina de hierro en Cantabria, aquí viven animales de cinco continentes en semilibertad. El parque es famoso por sus amplios recintos en un paisaje kárstico extraño.",
      pt: "Localizado numa antiga mina de ferro na Cantábria, aqui vivem animais de cinco continentes em semiliberdade. O parque é famoso pelos seus recintos amplos numa paisagem cárstica bizarra.",
      fr: "Situé dans une ancienne mine de fer en Cantabrie, des animaux de cinq continents y vivent en semi-liberté. Le parc est célèbre pour ses vastes enclos dans un paysage karstique étrange.",
    },
