    imageHint: "Faunia Madrid penguin exhibition",
    image: "/poi-images/spain-faunia-life-v2.webp",
    descriptionAdvanced: {
      de: "Faunia, im Osten der spanischen Hauptstadt Madrid gelegen, ist ein innovativer Biopark, der die Grenzen zwischen einem klassischen Zoo und einem großflächigen botanischen Garten aufbricht. Auf einem Areal von 14 Hektar widmet sich der Park nicht nach Kontinenten, sondern nach streng definierten Ökosystemen. Die Besucher durchwandern originalgetreue Nachbildungen von vier großen Klimazonen. Die unbestrittene Hauptattraktion ist das gewaltige polare Ökosystem, eines der größten Pinguinarien Europas, in dem Temperaturen knapp über dem Gefrierpunkt herrschen und in dem mehr als 100 Pinguine aus mehreren antarktischen und subantarktischen Arten leben. Ein weiterer Höhepunkt ist der riesige Dschungel-Pavillon, in dem subtropische Temperaturen und hohe Luftfeuchtigkeit ein authentisches Amazonas-Gefühl vermitteln, während kleine Affen, tropische Vögel und Flughunde völlig frei umherfliegen und klettern. Faunia bietet zudem ein faszinierendes nächtliches Ökosystem (Sombras Silenciosas) sowie ein giftiges, wo die gefährlichsten Insekten und Reptilien der Welt bestaunt werden können.",
      hu: "A spanyol főváros, Madrid keleti részén található Faunia egy innovatív biopark, amely elmossa a határokat a klasszikus állatkert és egy kiterjedt botanikus kert között. A 14 hektáros területen a park nem kontinensek, hanem szigorúan meghatározott ökoszisztémák szerint tagolódik. A látogatók négy nagy éghajlati zóna hű másolatain sétálhatnak keresztül. A vitathatatlan fő attrakció a hatalmas sarki ökoszisztéma, Európa egyik legnagyobb pingvináriuma, ahol fagypont feletti hőmérséklet uralkodik, és ahol több mint 100 pingvin él, amelyek különböző antarktiszi és szubantarktiszi fajokhoz tartoznak. További fénypont a hatalmas dzsungel pavilon, ahol a szubtrópusi hőmérséklet és a magas páratartalom autentikus Amazonas-élményt nyújt, miközben kis majmok, trópusi madarak és repülőkutyák teljesen szabadon repkednek és mászkálnak. A Faunia emellett egy lenyűgöző éjszakai ökoszisztémát (Csendes árnyak), valamint egy mérgező részleget is kínál, ahol a világ legveszélyesebb rovarai és hüllői csodálhatók meg.",
      ro: "Faunia, situat în estul capitalei spaniole Madrid, este un bioparc inovator care estompează granițele dintre o grădină zoologică clasică și o grădină botanică extinsă. Pe o suprafață de 14 hectare, parcul nu este dedicat continentelor, ci ecosistemelor strict definite. Vizitatorii se plimbă prin replici fidele a patru mari zone climatice. Atracția principală incontestabilă este ecosistemul polar masiv, unul dintre cele mai mari pinguinarii din Europa, unde temperaturile sunt chiar peste punctul de îngheț și unde trăiesc peste 100 de pinguini din mai multe specii antarctice și subantarctice. Un alt punct de atracție este uriașul pavilion al junglei, unde temperaturile subtropicale și umiditatea ridicată oferă o senzație autentică de Amazon, în timp ce maimuțe mici, păsări tropicale și vulpi zburătoare zboară și se cațără complet libere. Faunia oferă, de asemenea, un ecosistem nocturn fascinant (Umbre Tăcute) și o zonă veninoasă unde pot fi admirate cele mai periculoase insecte și reptile din lume.",
      en: "Faunia, located in the east of the Spanish capital Madrid, is an innovative biopark that breaks down the boundaries between a classic zoo and an extensive botanical garden. Covering an area of 14 hectares, the park is organized not by continents, but by strictly defined ecosystems. Visitors wander through faithful replicas of four major climatic zones. The undisputed main attraction is the massive polar ecosystem, one of the largest penguinariums in Europe, where temperatures hover just above freezing and more than 100 penguins from several Antarctic and sub-Antarctic species reside. Another highlight is the giant jungle pavilion, where subtropical temperatures and high humidity provide an authentic Amazonian feel, while small monkeys, tropical birds, and flying foxes fly and climb completely freely. Faunia also offers a fascinating nocturnal ecosystem (Silent Shadows) as well as a venomous section where the world's most dangerous insects and reptiles can be marveled at.",
      es: "Faunia, situado al este de la capital española, Madrid, es un bioparque innovador que rompe las fronteras entre un zoológico clásico y un gran jardín botánico. En un área de 14 hectáreas, el parque no se dedica por continentes, sino por ecosistemas estrictamente definidos. Los visitantes recorren reproducciones fieles de cuatro grandes zonas climáticas. La atracción principal indiscutible es el gigantesco ecosistema polar, uno de los pingüinarios más grandes de Europa, donde las temperaturas están justo por encima del punto de congelación y donde viven más de 100 pingüinos de varias especies antárticas y subantárticas. Otro punto culminante es el enorme pabellón de la selva, donde las temperaturas subtropicales y la alta humedad transmiten una auténtica sensación amazónica, mientras pequeños monos, aves tropicales y zorros voladores vuelan y trepan libremente. Faunia también ofrece un fascinante ecosistema nocturno (Sombras Silenciosas), así como uno tóxico, donde se pueden admirar los insectos y reptiles más peligrosos del mundo.",
      pt: "Faunia, localizado a leste da capital espanhola, Madrid, é um bioparque inovador que quebra as fronteiras entre um zoológico clássico e um grande jardim botânico. Numa área de 14 hectares, o parque não é dedicado por continentes, mas por ecossistemas estritamente definidos. Os visitantes percorrem reproduções fiéis de quatro grandes zonas climáticas. A atração principal indiscutível é o gigantesco ecossistema polar, um dos maiores pinguinários da Europa, onde as temperaturas estão logo acima do ponto de congelamento e onde vivem mais de 100 pinguins de várias espécies antárticas e subantárticas. Outro destaque é o enorme pavilhão da selva, onde as temperaturas subtropicais e a alta humidade transmitem uma autêntica sensação amazónica, enquanto pequenos macacos, aves tropicais e raposas-voadoras voam e trepam livremente. Faunia também oferece um fascinante ecossistema noturno (Sombras Silenciosas), bem como um tóxico, onde se podem admirar os insetos e répteis mais perigosos do mundo.",
      fr: "Faunia, situé à l'est de la capitale espagnole, Madrid, est un bioparc innovant qui brise les frontières entre un zoo classique et un grand jardin botanique. Sur une superficie de 14 hectares, le parc n'est pas organisé par continents, mais par écosystèmes strictement définis. Les visiteurs parcourent des reproductions fidèles de quatre grandes zones climatiques. L'attraction principale incontestée est le gigantesque écosystème polaire, l'un des plus grands manchotiers d'Europe, où les températures sont juste au-dessus du point de congélation et où vivent plus de 100 manchots de plusieurs espèces antarctiques et subantarctiques. Un autre point fort est l'immense pavillon de la jungle, où les températures subtropicales et l'humidité élevée transmettent une authentique sensation amazonienne, tandis que de petits singes, des oiseaux tropicaux et des roussettes volent et grimpent librement. Faunia propose également un écosystème nocturne fascinant (Sombras Silenciosas) ainsi qu'un écosystème toxique, où l'on peut admirer les insectes et reptiles les plus dangereux du monde.",
    },
