      en: ["The park covers 14 hectares in the eastern part of Madrid.", "Houses more than 3,000 animals from over 300 different species.", "The penguinarium maintains a constant temperature between 0 and 2 degrees Celsius.", "The jungle pavilion replicates a tropical rainstorm every 15 minutes.", "The park features a special area dedicated to nocturnal animals ('Silent Shadows').", "More than 15,000 plant species grow across the entire grounds."],
