    imageHint: "Gallocanta Lake cranes flying at sunset",
    descriptionAdvanced: {
      de: "Der Gallocanta-See im iberischen Hochland der Region Aragonien ist ein Naturphänomen von kontinentaler Bedeutung. Es handelt sich um eine gewaltige abflusslose Senke (endorheisches Becken) auf fast 1.000 Metern Höhe, die Spaniens größten natürlichen Salzsee bildet. Je nach Jahreszeit und Niederschlagsmenge variiert die Wasserfläche extrem – in heißen, trockenen Sommern kann der See fast vollständig austrocknen und eine glitzernde weiße Salzkruste hinterlassen. Die wahre Magie von Gallocanta entfaltet sich jedoch im späten Herbst und zeitigen Frühjahr. Dann wird der See zum wichtigsten Rastplatz für den europäischen Kranichzug. Zu Spitzenzeiten versammeln sich hier bis zu 60.000 majestätische Kraniche auf ihrer langen Reise zwischen Nordeuropa und den Überwinterungsgebieten in Südspanien und Nordafrika. Das trompetenartige Rufen zehntausender Vögel, wenn sie im rötlichen Licht der Dämmerung in gigantischen V-Formationen vom See auffliegen, gehört zu den spektakulärsten Naturschauspielen in ganz Südeuropa.",
      hu: "Az Aragónia régió ibériai fennsíkján fekvő Gallocanta-tó kontinentális jelentőségű természeti jelenség. Ez egy hatalmas, lefolyástalan medence (endorheikus medence) közel 1000 méteres magasságban, amely Spanyolország legnagyobb természetes sós tavát alkotja. Az évszaktól és a csapadékmennyiségtől függően a vízfelület rendkívül változó – forró, száraz nyarakon a tó szinte teljesen kiszáradhat, és csillogó fehér sókérget hagyhat maga után. Gallocanta igazi varázsa azonban késő ősszel és kora tavasszal bontakozik ki. Ekkor a tó az európai daruvonulás legfontosabb pihenőhelyévé válik. Csúcsidőben akár 60 000 fenséges daru is összegyűlik itt, miközben hosszú utat tesznek meg Észak-Európa, valamint a dél-spanyolországi és észak-afrikai telelőhelyek között. A több tízezer madár trombitáló hívóhangja, amint hatalmas V alakzatokban felszállnak a tóról az alkonyat vöröses fényében, egész Dél-Európa egyik leglátványosabb természeti jelensége.",
      ro: "Lacul Gallocanta din podișul iberic al regiunii Aragon este un fenomen natural de importanță continentală. Este o imensă depresiune fără scurgere (bazin endoreic) la o altitudine de aproape 1.000 de metri, formând cel mai mare lac sărat natural din Spania. În funcție de sezon și de precipitații, suprafața apei variază extrem de mult – în verile toride și uscate, lacul poate seca aproape complet, lăsând în urmă o crustă de sare albă strălucitoare. Cu toate acestea, adevărata magie a Gallocantei se dezvăluie la sfârșitul toamnei și începutul primăverii. Atunci, lacul devine cel mai important loc de popas pentru migrația cocorilor europeni. În perioadele de vârf, până la 60.000 de cocori maiestuoși se adună aici în lunga lor călătorie între Europa de Nord și zonele de iernat din sudul Spaniei și nordul Africii. Chemarea asemănătoare trâmbițelor a zeci de mii de păsări, atunci când își iau zborul de pe lac în formațiuni gigantice în formă de V în lumina roșiatică a crepusculului, este unul dintre cele mai spectaculoase fenomene naturale din întreaga Europă de Sud.",
      en: "Lake Gallocanta, located in the Iberian highlands of the Aragon region, is a natural phenomenon of continental significance. It is a massive closed drainage basin (endorheic basin) situated at an altitude of nearly 1,000 meters, forming Spain's largest natural salt lake. Depending on the season and rainfall, the water surface area varies extremely—during hot, dry summers, the lake can dry out almost completely, leaving behind a glistening white salt crust. The true magic of Gallocanta, however, unfolds in late autumn and early spring. During these times, the lake becomes the most crucial stopover point for the European crane migration. At peak times, up to 60,000 majestic common cranes gather here on their long journey between Northern Europe and their wintering grounds in southern Spain and North Africa. The trumpeting call of tens of thousands of birds as they take flight from the lake in giant V-formations against the reddish glow of dusk is one of the most spectacular natural events in all of Southern Europe.",
      es: "La Laguna de Gallocanta, en el altiplano de la región de Aragón, es un fenómeno natural de importancia continental. Se trata de una inmensa cuenca endorreica a casi 1.000 metros de altitud, que constituye el mayor lago salado natural de España. Según la estación y las precipitaciones, la superficie del agua varía drásticamente; en veranos calurosos y secos, el lago puede secarse casi por completo, dejando una brillante costra de sal blanca. Sin embargo, la verdadera magia de Gallocanta se despliega a finales de otoño y principios de primavera, convirtiéndose en el lugar de escala más importante para la migración de la grulla común. En momentos de máxima afluencia, hasta 60.000 majestuosas grullas se reúnen aquí en su largo viaje entre el norte de Europa y las zonas de invernada en el sur de España y el norte de África. El sonido de trompeteo de decenas de miles de aves al despegar en gigantescas formaciones en V bajo la luz rojiza del crepúsculo es uno de los espectáculos naturales más espectaculares de todo el sur de Europa.",
      pt: "A Laguna de Gallocanta, no planalto da região de Aragão, é um fenómeno natural de importância continental. Trata-se de uma imensa bacia endorreica a quase 1.000 metros de altitude, que constitui o maior lago salgado natural de Espanha. Dependendo da estação e da precipitação, a superfície da água varia drasticamente; em verões quentes e secos, o lago pode secar quase completamente, deixando uma crosta de sal branca e brilhante. No entanto, a verdadeira magia de Gallocanta desdobra-se no final do outono e início da primavera, tornando-se o local de repouso mais importante para a migração da grou-comum. Nos momentos de maior afluência, até 60.000 majestosos grous reúnem-se aqui na sua longa viagem entre o norte da Europa e as zonas de invernada no sul de Espanha e norte de África. O som de trombeta de dezenas de milhares de aves ao levantar voo em gigantescas formações em V sob a luz avermelhada do crepúsculo é um dos espetáculos naturais mais espetaculares de todo o sul da Europa.",
      fr: "La lagune de Gallocanta, sur le haut plateau de la région d'Aragon, est un phénomène naturel d'importance continentale. Il s'agit d'un immense bassin endoréique situé à près de 1 000 mètres d'altitude, qui constitue le plus grand lac salé naturel d'Espagne. Selon la saison et les précipitations, la surface de l'eau varie considérablement ; durant les étés chauds et secs, le lac peut presque s'assécher complètement, laissant une croûte de sel blanc étincelante. Cependant, la véritable magie de Gallocanta se révèle à la fin de l'automne et au début du printemps, lorsqu'il devient la halte migratoire la plus importante pour la grue cendrée. Aux pics d'affluence, jusqu'à 60 000 grues majestueuses se rassemblent ici lors de leur long voyage entre l'Europe du Nord et les zones d'hivernage dans le sud de l'Espagne et en Afrique du Nord. Le cri de trompette de dizaines de milliers d'oiseaux s'envolant en formations en V géantes sous la lumière rougeâtre du crépuscule est l'un des spectacles naturels les plus impressionnants de tout le sud de l'Europe.",
    },
