      hu: ["A maga 14 négyzetkilométerével ez Spanyolország legnagyobb lefolyástalan tava.", "Kivételes, 990 méteres tengerszint feletti magasságban fekszik.", "A madárvonulás idején akár 60 000 daru is összegyűlhet itt egyszerre.", "A tónak nincs természetes lefolyása a tengerbe.", "1994-ben a lagúnát hivatalosan is Ramsari területté nyilvánították.", "A víz sótartalma nyáron magasabb lehet, mint a tengervízé."],
      ro: ["Cu 14 kilometri pătrați, este cel mai mare lac endoreic din Spania.", "Este situat la o altitudine excepțională de 990 de metri deasupra nivelului mării.", "Până la 60.000 de cocori se adună aici simultan în timpul migrației.", "Lacul nu are o scurgere naturală către mare.", "În 1994, laguna a fost declarată oficial sit Ramsar.", "Salinitatea apei vara poate fi mai mare decât cea a apei de mare."],
      en: ["Spanning 14 square kilometers, it is Spain's largest endorheic lake.", "It is situated at an exceptional altitude of 990 meters above sea level.", "Up to 60,000 common cranes gather here simultaneously during migration.", "The lake has no natural outflow to the sea.", "In 1994, the lagoon was officially declared a Ramsar wetland site.", "The water's salinity in summer can be higher than that of seawater."],
      es: ["Con 14 kilómetros cuadrados, es el lago endorreico más grande de España.", "Se encuentra a una altitud excepcional de 990 metros sobre el nivel del mar.", "Se reúnen hasta 60.000 grullas simultáneamente durante la migración.", "El lago no tiene salida natural al mar.", "En 1994, la laguna fue declarada oficialmente zona Ramsar.", "La salinidad del agua puede ser mayor en verano que la del agua de mar."],
      pt: ["Com 14 quilómetros quadrados, é o maior lago endorreico de Espanha.", "Situa-se a uma altitude excecional de 990 metros acima do nível do mar.", "Reúnem-se até 60.000 grous simultaneamente durante a migração.", "O lago não tem saída natural para o mar.", "Em 1994, a lagoa foi oficialmente declarada zona Ramsar.", "A salinidade da água pode ser maior no verão do que a da água do mar."],
      fr: ["Avec 14 kilomètres carrés, c'est le plus grand lac endoréique d'Espagne.", "Il se situe à une altitude exceptionnelle de 990 mètres au-dessus du niveau de la mer.", "Jusqu'à 60 000 grues se rassemblent simultanément pendant la migration.", "Le lac n'a pas d'exutoire naturel vers la mer.", "En 1994, la lagune a été officiellement déclarée zone Ramsar.", "La salinité de l'eau peut être plus élevée en été que celle de l'eau de mer."],
